-- Reportes_911_2026_20000.sql
-- Dataset SINTÉTICO para prácticas de SQL y análisis de datos.
-- 20,000 registros ficticios de 2026.
-- Clasificaciones e incidentes basados en el Catálogo Nacional de Incidentes de Emergencia v.2.0.
-- Personas, folios, calles y ubicaciones son ficticios.
-- Coordenadas: aproximaciones sintéticas dentro de Morelos y municipios cercanos.

DROP DATABASE IF EXISTS `Reportes_911`;
CREATE DATABASE `Reportes_911`;
USE `Reportes_911`;

CREATE TABLE Incidencias_2026 (
  folio INT NOT NULL,
  municipio VARCHAR(50),
  tipo VARCHAR(50),
  codigo_incidente INT,
  fecha DATE,
  hora TIME,
  incidente VARCHAR(150),
  prioridad VARCHAR(20),
  sexo VARCHAR(20),
  colonia VARCHAR(80),
  calle VARCHAR(80),
  coordenadas POINT NOT NULL,
  PRIMARY KEY (folio)
);





















